-- The 11 monsters need a full-fidelity mythic creature representation.
-- The sample builds and rules hub have no corresponding indexed-content tables.
-- Their absence is not counted as passing coverage.

create temporary table war_index_expected (
  category text not null,
  index_name text not null,
  table_name text not null,
  wg_id bigint,
  wg_uuid bigint not null,
  wg_name text not null,
  index_url text not null,
  stored_url text not null
);


create temporary table war_index_epithets (
  index_name text not null,
  index_url text not null,
  parent_id bigint not null,
  choice_id text not null,
  wg_name text not null
);


create temporary view war_index_actual as
  select 'ability_block'::text as table_name, id, uuid, name, content_source_id,
    meta_data #>> '{source,book}' as book, meta_data #>> '{source,url}' as url
  from public.ability_block where content_source_id = 400
  union all select 'archetype', id, uuid, name, content_source_id,
    meta_data #>> '{source,book}', meta_data #>> '{source,url}'
  from public.archetype where content_source_id = 400
  union all select 'class_archetype', id, uuid, name, content_source_id,
    meta_data #>> '{source,book}', meta_data #>> '{source,url}'
  from public.class_archetype where content_source_id = 400
  union all select 'class', id, uuid, name, content_source_id,
    meta_data #>> '{source,book}', meta_data #>> '{source,url}'
  from public.class where content_source_id = 400
  union all select 'item', id, uuid, name, content_source_id,
    meta_data #>> '{source,book}', meta_data #>> '{source,url}'
  from public.item where content_source_id = 400
  union all select 'spell', id, uuid, name, content_source_id,
    meta_data #>> '{source,book}', meta_data #>> '{source,url}'
  from public.spell where content_source_id = 400
  union all select 'trait', id, uuid, name, content_source_id,
    meta_data #>> '{source,book}', meta_data #>> '{source,url}'
  from public.trait where content_source_id = 400;

create temporary view war_index_checks as
select 'war-index-standalone'::text as id,
  (select count(*) = 461 from war_index_expected)
  and (select count(distinct (table_name, wg_uuid)) = 461 from war_index_expected)
  and not exists (
    select 1 from war_index_expected expected
    where (select count(*) from war_index_actual actual
      where actual.table_name = expected.table_name
        and (expected.wg_id is null or actual.id = expected.wg_id)
        and actual.uuid = expected.wg_uuid
        and actual.name = expected.wg_name
        and actual.book = 'War of Immortals'
        and actual.url = expected.stored_url
    ) <> 1
  ) as passed
union all
select 'war-index-epithets',
  (select count(*) = 16 from war_index_epithets)
  and (select count(distinct choice_id) = 16 from war_index_epithets)
  and not exists (
    select 1 from war_index_epithets expected
    where not exists (
      select 1
      from public.ability_block parent
      cross join lateral unnest(parent.operations) operation
      cross join lateral jsonb_array_elements(operation::jsonb #> '{data,optionsPredefined}') choice
      where parent.id = expected.parent_id
        and parent.content_source_id = 400
        and choice->>'id' = expected.choice_id
        and choice->>'title' = expected.wg_name
        and nullif(choice->>'description', '') is not null
    )
  );

select id, passed from war_index_checks order by id;
